1	'use client';
2	import {useCallback, useEffect, useState} from 'react';
3	import {ArrowRight, Heart, ShoppingBag, Search, Sparkles, Database, Boxes, Cpu, SlidersHorizontal, X} from 'lucide-react';
4	
5	type Product = {id:string;title:string;description:string;category:string;brand:string;price:number;currency:string;image_url:string;rating:number};
6	type Result = {items:Product[]; provider?:string; strategy?:string; total?:number};
7	const fetchJSON = async (path:string, options?:RequestInit) => {
8	  const response = await fetch(path, {credentials:'same-origin', ...options});
9	  if(!response.ok) throw new Error(`API error: ${response.status}`);
10	  return response.json();
11	};
12	export default function Home() {
13	  const [items, setItems] = useState<Product[]>([]);
14	  const [suggested, setSuggested] = useState<Product[]>([]);
15	  const [categories, setCategories] = useState<string[]>([]);
16	  const [category, setCategory] = useState('');
17	  const [query, setQuery] = useState('');
18	  const [draft, setDraft] = useState('');
19	  const [selected, setSelected] = useState<Product|null>(null);
20	  const [cart, setCart] = useState(0);
21	  const [provider, setProvider] = useState('local');
22	  const [strategy, setStrategy] = useState('local');
23	  const [error, setError] = useState('');
24	  const reload = useCallback(async (signal?:AbortSignal) => {
25	    try {
26	      const data: Result = query ? await fetchJSON(`/api/search?q=${encodeURIComponent(query)}&category=${encodeURIComponent(category)}`, {signal})
27	        : await fetchJSON(`/api/products?limit=60&category=${encodeURIComponent(category)}`, {signal});
28	      if(signal?.aborted) return;
29	      setItems(data.items); setProvider(data.provider || 'database'); setError('');
30	    } catch {if(!signal?.aborted) setError('API 尚未连接。请启动 Mac 上的 FastAPI。');}
31	  }, [query,category]);
32	  const refreshRecommendations = useCallback(async () => {
33	    try {const result:Result = await fetchJSON('/api/recommendations/home?limit=8');setSuggested(result.items);setStrategy(result.strategy || 'local');} catch { /* optional */ }
34	  }, []);
35	  useEffect(() => {const controller = new AbortController(); reload(controller.signal); return () => controller.abort();}, [reload]);
36	  useEffect(() => {refreshRecommendations();fetchJSON('/api/categories').then(setCategories).catch(()=>{});fetchJSON('/api/cart').then(r=>setCart(r.items.reduce((n:number, i:{quantity:number})=>n+i.quantity,0))).catch(()=>{});}, [refreshRecommendations]);
37	  const emit = async (product:Product, event_type:'click'|'favorite'|'cart') => {
38	    try {await fetchJSON('/api/events', {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({product_id:product.id,event_type})});} catch { /* do not block browsing */ }
39	    refreshRecommendations();
40	  };
41	  const addCart = async (p:Product) => {
42	    try {await fetchJSON('/api/cart',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({product_id:p.id,quantity:1})});setCart(c=>c+1);refreshRecommendations();}
43	    catch {setError('购物车操作失败，请检查 API。');}
44	  };
45	  const card = (p:Product, i:number) => <article className="product-card" key={p.id}>
46	    <button className="photo" onClick={()=>{setSelected(p);emit(p,'click');}} aria-label={`查看${p.title}`}>
47	      {p.image_url ? <img src={p.image_url} alt={p.title} loading="lazy" /> : <span className="product-monogram">{p.category.slice(0,1)}</span>}
48	      <span className="category-tag">{p.category}</span>
49	    </button>
50	    <div className="card-body">
51	      <span className="brand">{p.brand || 'Marketplace'}</span>
52	      <button className="product-name" onClick={()=>{setSelected(p);emit(p,'click');}}>{p.title}</button>
53	      <div className="card-bottom"><strong>{p.currency==='USD'?'$':'¥'}{p.price.toFixed(2)}</strong><button className="add" onClick={()=>addCart(p)} aria-label="加入购物车">+</button></div>
54	    </div>
55	  </article>;
56	  return <main className="min-h-screen">
57	    <div className="announcement">DISTRIBUTED COMMERCE LAB <span>·</span> 三节点局域网推荐实验平台 <ArrowRight size={12}/></div>
58	    <header className="topbar"><div className="logo"><div className="logo-mark">◈</div><span>orbit<span className="logo-thin">market</span></span></div>
59	      <div className="searchbar"><Search size={19}/><input value={draft} placeholder="搜索商品、品牌、分类..." onChange={e=>setDraft(e.target.value)} onKeyDown={e=>e.key==='Enter'&&setQuery(draft.trim())}/><button onClick={()=>setQuery(draft.trim())}>搜索</button></div>
60	      <div className="header-actions"><button title="展示收藏功能" onClick={()=>document.getElementById('catalog')?.scrollIntoView({behavior:'smooth'})}><Heart size={21}/></button><button className="cart-pill" title="演示购物车"><ShoppingBag size={20}/><span>{cart}</span></button></div>
61	    </header>
62	    <section className="hero"><div><div className="eyebrow"><Sparkles size={14}/> INTELLIGENT DISCOVERY</div><h1>发现真正<br/><em>适合你的</em> 好物。</h1><p>连接搜索、发现与偏好的新一代商品实验商城。由三台计算机共同驱动的个性化探索之旅。</p><button className="hero-btn" onClick={()=>document.getElementById('catalog')?.scrollIntoView({behavior:'smooth'})}>探索商品 <ArrowRight size={18}/></button></div>
63	      <div className="hero-art"><div className="hero-orb">◈</div><span className="art-label">INTELLIGENCE IN MOTION</span></div></section>
64	    <section className="cluster"><div><Database size={18}/><span>Ubuntu A · 数据与检索</span></div><div><Cpu size={18}/><span>Ubuntu B · 推荐计算</span></div><div><Boxes size={18}/><span>macOS · 网页与 API</span></div><span className="status-label">● LAN LAB</span></section>
65	    <section className="section" id="catalog"><div className="section-heading"><div><span className="overline">CURATED CATALOG</span><h2>{query ? `搜索结果：${query}` : '探索精选商品'}</h2><p>从真实数据集或本地演示数据中发现商品 · 搜索来源：{provider}</p></div><div className="filter-label"><SlidersHorizontal size={16}/> 精选集合</div></div>
66	      <div className="chips"><button className={!category?'active':''} onClick={()=>setCategory('')}>全部商品</button>{categories.map(c=><button key={c} className={c===category?'active':''} onClick={()=>setCategory(c)}>{c}</button>)}</div>
67	      {error && <p className="alert">{error}</p>}
68	      <div className="catalog-grid">{items.map(card)}</div>{items.length===0&&!error&&<p className="empty">暂无商品。首次部署请执行示例数据导入。</p>}
69	    </section>
70	    <section className="section rec-section"><div className="section-heading"><div><span className="overline">JUST FOR YOU</span><h2>猜你喜欢 <span className="stars">✳</span></h2><p>根据你的浏览偏好动态调整 · 策略：{strategy}</p></div><button className="subtle-btn" onClick={refreshRecommendations}>更新推荐 <ArrowRight size={16}/></button></div><div className="catalog-grid">{suggested.map(card)}</div></section>
71	    <footer><span>◈ orbitmarket</span><span>Research demonstration · Prices and stock are not live offers · 2026</span></footer>
72	    {selected&&<div className="modal-backdrop" onClick={()=>setSelected(null)}><div className="modal" role="dialog" aria-modal="true" aria-label={selected.title} onClick={e=>e.stopPropagation()}><button className="close" onClick={()=>setSelected(null)}><X/></button><div className="modal-photo">{selected.image_url?<img src={selected.image_url} alt=""/>:<span className="product-monogram">{selected.category.slice(0,1)}</span>}</div><div className="modal-copy"><span className="overline">{selected.category} · {selected.brand}</span><h2>{selected.title}</h2><p>{selected.description||'暂无详细描述。'}</p><div className="modal-price">{selected.currency==='USD'?'$':'¥'}{selected.price.toFixed(2)}</div><button className="hero-btn" onClick={()=>{addCart(selected);setSelected(null);}}>加入演示购物车 <ShoppingBag size={18}/></button><small>仅用于研究展示，不接受真实交易。</small></div></div></div>}
73	  </main>;
74	}
